extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi correttamente"):
		return

	var enemies_array = get_prop(main, "enemies")
	if not check("enemies_prop", typeof(enemies_array) == TYPE_ARRAY, "enemy_manager.gd deve definire l'Array enemies"):
		return

	check("initial_count", enemies_array.size() == 4, "Inizialmente ci devono essere 4 nemici nell'Array enemies")

	if has_function(main, "hit_all_enemies"):
		main.call("hit_all_enemies", 100)

	if has_function(main, "process_hits"):
		main.call("process_hits")

	check("all_enemies_removed", enemies_array.size() == 0, "Dopo aver eliminato tutti i nemici, l'Array enemies deve essere vuoto")
	check("no_runtime_errors", errors_text() == "", "La rimozione non deve causare errori nel Debugger")

