extends Node2D

var enemies: Array[Sprite2D] = []


func _ready() -> void:
	# Crea 4 nemici nell'Array
	var enemy_scene: PackedScene = load("res://enemy.tscn")
	for i in range(4):
		var enemy: Sprite2D = enemy_scene.instantiate() as Sprite2D
		enemy.position = Vector2(100.0 + i * 120.0, 200.0)
		add_child(enemy)
		enemies.append(enemy)


func hit_all_enemies(damage: int) -> void:
	for enemy in enemies:
		enemy.take_damage(damage)


func process_hits() -> void:
	# ERRORE: ciclo in avanti che fallisce durante le eliminazioni multiple!
	for i in range(enemies.size()):
		if enemies[i].health <= 0:
			remove_child(enemies[i])
			enemies.remove_at(i)

extends Node2D

var enemies: Array[Sprite2D] = []


func _ready() -> void:
	# Crea 4 nemici nell'Array
	var enemy_scene: PackedScene = load("res://enemy.tscn")
	for i in range(4):
		var enemy: Sprite2D = enemy_scene.instantiate() as Sprite2D
		enemy.position = Vector2(100.0 + i * 120.0, 200.0)
		add_child(enemy)
		enemies.append(enemy)


func hit_all_enemies(damage: int) -> void:
	for enemy in enemies:
		enemy.take_damage(damage)


func process_hits() -> void:
	# Corretto: scorre l'Array all'indietro dall'ultimo elemento verso il primo
	for i in range(enemies.size() - 1, -1, -1):
		if enemies[i].health <= 0:
			remove_child(enemies[i])
			enemies.remove_at(i)
